def _current_round_gate_artifact_path(
    state_dir: Path,
    artifact_name: str,
    output_path: str,
    *,
    decision_id: str,
    round_id: str,
) -> str | None:
    payload = _read_json(state_dir / "gates" / artifact_name)
    if _artifact_matches_current_round(
        payload,
        decision_id=decision_id,
        round_id=round_id,
    ):
        return output_path
    return None

