def _project_job_schema_validation_check(
    *,
    repo_root: Path,
    decision_contract: dict[str, Any],
) -> dict[str, Any]:
    required = bool(decision_contract.get("accepted_requires_minimal_job_schema_validation"))
    try:
        from reverse_agent import project_jobs
    except Exception as exc:
        return _check(
            "project_job_schema_validation",
            "FAIL" if required else "PASS",
            "project_jobs validator import failed"
            if required
            else "project_jobs validator not required and import failed",
            required=required,
            error=str(exc),
        )

    sample_payload = {
        "schema_version": project_jobs.JOB_SCHEMA_VERSION,
        "job_id": "job_preflight_foundation",
        "round_id": "round_preflight_foundation",
        "decision_id": "decision_preflight_foundation",
        "mainline": "engineering_branch",
        "status": "READY",
        "runner": {"kind": "codex", "dispatch_enabled": False},
        "required_inputs": ["project_state/decision_packet.md"],
        "required_outputs": ["project_state/gates/preflight_result.json"],
        "permissions": {
            "allow_remote_mutation": False,
            "allow_llm_calls": False,
            "allow_agent_dispatch": False,
            "allow_reverse_solving": False,
        },
        "budgets": {"max_runtime_seconds": 1500, "max_commands": 8},
    }
    valid_result = project_jobs.validate_job_payload(sample_payload)
    invalid_payload = dict(sample_payload)
    invalid_payload["runner"] = {"kind": "codex", "dispatch_enabled": True}
    invalid_result = project_jobs.validate_job_payload(invalid_payload)
    required_statuses = {
        "DRAFT",
        "READY",
        "RUNNING",
        "DONE",
        "FINAL_CHECKED",
        "AUDITED",
        "ACCEPTED",
        "ACCEPTED_WITH_LIMITATIONS",
        "REWORK_REQUIRED",
        "BLOCKED",
    }
    missing_statuses = sorted(required_statuses - set(project_jobs.JOB_STATUSES))
    job_files = sorted(
        str(path.relative_to(repo_root)).replace("\\", "/")
        for path in (repo_root / "project_state" / "jobs").glob("*.json")
    ) if (repo_root / "project_state" / "jobs").exists() else []
    job_file_results = []
    job_file_errors = []
    for rel_path in job_files:
        result = project_jobs.validate_job_file(repo_root / rel_path)
        job_file_results.append({"path": rel_path, "validation_status": result.get("validation_status")})
        if result.get("validation_status") != "PASSED":
            job_file_errors.append({"path": rel_path, "errors": result.get("errors") or []})

    ok = (
        valid_result.get("validation_status") == "PASSED"
        and invalid_result.get("validation_status") == "FAILED"
        and not missing_statuses
        and not job_file_errors
    )
    return _check(
        "project_job_schema_validation",
        "PASS" if ok else "FAIL",
        "project job schema validator is present, non-dispatching, and validates any project_state/jobs/*.json files"
        if ok
        else "project job schema validator is missing required behavior or job files failed validation",
        required=required,
        validator="reverse_agent/project_jobs.py",
        test_file="tests/test_project_jobs.py",
        missing_statuses=missing_statuses,
        sample_validation_status=valid_result.get("validation_status"),
        dispatch_rejection_status=invalid_result.get("validation_status"),
        job_files=job_file_results,
        job_file_errors=job_file_errors,
    )


def jobs_inventory(*, state_dir: Path, write_result: bool = True) -> dict[str, Any]:
    """Validate project_state/jobs through the existing project_jobs inventory API."""
    state_dir = Path(state_dir)
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    round_id = str(decision.get("round_id") or "")
    mainline = str(decision.get("mainline") or "")

    def _inventory_path(value: object) -> str:
        text = _norm_path(value)
        if not text:
            return ""
        path = Path(text)
        try:
            return _norm_path(path.resolve().relative_to(state_dir.parent.resolve()))
        except (OSError, ValueError):
            return text

    errors: list[str] = []
    warnings: list[str] = []
    try:
        from reverse_agent import project_jobs
    except Exception as exc:
        inventory: dict[str, Any] = {
            "validation_status": "FAILED",
            "job_count": 0,
            "status_counts": {},
            "validated_paths": [],
            "jobs": [],
            "dispatch_enabled": False,
        }
        errors.append(f"project_jobs import failed: {exc}")
    else:
        inventory = project_jobs.validate_jobs_dir(state_dir)
        errors.extend(str(item) for item in inventory.get("errors") or [])
        warnings.extend(str(item) for item in inventory.get("warnings") or [])

    duplicate_job_errors = [
        error for error in errors if "duplicate job_id" in error.lower()
    ]
    invalid_file_errors = [
        error for error in errors if "duplicate job_id" not in error.lower()
    ]
    dispatch_enabled = bool(inventory.get("dispatch_enabled"))
    dispatch_safety_status = "FAILED" if dispatch_enabled else "PASSED"
    validation_status = str(inventory.get("validation_status") or "FAILED")
    gate_status = (
        "PASSED"
        if validation_status == "PASSED" and dispatch_safety_status == "PASSED"
        else "FAILED"
    )

    result = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "artifact_name": JOBS_INVENTORY_RESULT_NAME,
        "gate_name": JOBS_INVENTORY_NAME,
        "gate_status": gate_status,
        "decision_id": decision_id,
        "round_id": round_id,
        "mainline": mainline,
        "generated_at": _now_iso(),
        "inventory_validation_status": validation_status,
        "job_count": int(inventory.get("job_count") or 0),
        "status_counts": inventory.get("status_counts") or {},
        "validated_paths": sorted(_inventory_path(path) for path in inventory.get("validated_paths") or []),
        "jobs_dir": _inventory_path(inventory.get("jobs_dir")),
        "jobs": inventory.get("jobs") or [],
        "duplicate_job_errors": duplicate_job_errors,
        "invalid_file_errors": invalid_file_errors,
        "errors": errors,
        "warnings": warnings,
        "dispatch_enabled": dispatch_enabled,
        "dispatch_safety_status": dispatch_safety_status,
        "generated_artifacts": [JOBS_INVENTORY_OUTPUT_PATH],
    }

    if write_result:
        out_dir = state_dir / "gates"
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / JOBS_INVENTORY_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
    return result


def _jobs_inventory_gate_check(
    *,
    state_dir: Path,
    decision_id: str,
    round_id: str,
    decision_contract: dict[str, Any],
) -> dict[str, Any]:
    required = bool(decision_contract.get("accepted_requires_jobs_inventory_gate_artifact"))
    path = state_dir / "gates" / JOBS_INVENTORY_RESULT_NAME
    payload = _read_json(path)
    if not payload:
        return _check(
            "jobs_inventory_gate_artifact",
            "FAIL" if required else "PASS",
            "jobs inventory gate artifact is missing"
            if required
            else "jobs inventory gate artifact not required and not present",
            required=required,
            artifact=JOBS_INVENTORY_OUTPUT_PATH,
        )

    errors: list[str] = []
    if str(payload.get("decision_id") or "") != decision_id:
        errors.append("decision_id mismatch")
    if str(payload.get("round_id") or "") != round_id:
        errors.append("round_id mismatch")
    if errors and not required:
        return _check(
            "jobs_inventory_gate_artifact",
            "PASS",
            "jobs inventory gate artifact is stale and not required for this decision",
            required=required,
            artifact=JOBS_INVENTORY_OUTPUT_PATH,
            errors=errors,
            gate_status=payload.get("gate_status"),
            inventory_validation_status=payload.get("inventory_validation_status"),
            job_count=payload.get("job_count"),
            status_counts=payload.get("status_counts"),
            validated_paths=payload.get("validated_paths"),
            duplicate_job_errors=payload.get("duplicate_job_errors"),
            invalid_file_errors=payload.get("invalid_file_errors"),
            dispatch_safety_status=payload.get("dispatch_safety_status"),
        )
    if str(payload.get("gate_name") or "") != JOBS_INVENTORY_NAME:
        errors.append("gate_name mismatch")
    if str(payload.get("gate_status") or "") != "PASSED":
        errors.append("gate_status is not PASSED")
    if str(payload.get("inventory_validation_status") or "") != "PASSED":
        errors.append("inventory_validation_status is not PASSED")
    if str(payload.get("dispatch_safety_status") or "") != "PASSED":
        errors.append("dispatch_safety_status is not PASSED")
    if bool(payload.get("dispatch_enabled")):
        errors.append("dispatch_enabled is true")
    if not isinstance(payload.get("status_counts"), dict):
        errors.append("status_counts is not an object")
    if not isinstance(payload.get("validated_paths"), list):
        errors.append("validated_paths is not a list")
    if not isinstance(payload.get("duplicate_job_errors"), list):
        errors.append("duplicate_job_errors is not a list")
    if not isinstance(payload.get("invalid_file_errors"), list):
        errors.append("invalid_file_errors is not a list")
    if not isinstance(payload.get("job_count"), int):
        errors.append("job_count is not an integer")

    ok = not errors
    return _check(
        "jobs_inventory_gate_artifact",
        "PASS" if ok else "FAIL",
        "jobs inventory gate artifact is current, non-dispatching, and validated"
        if ok
        else "jobs inventory gate artifact is missing required current validation evidence",
        required=required,
        artifact=JOBS_INVENTORY_OUTPUT_PATH,
        errors=errors,
        gate_status=payload.get("gate_status"),
        inventory_validation_status=payload.get("inventory_validation_status"),
        job_count=payload.get("job_count"),
        status_counts=payload.get("status_counts"),
        validated_paths=payload.get("validated_paths"),
        duplicate_job_errors=payload.get("duplicate_job_errors"),
        invalid_file_errors=payload.get("invalid_file_errors"),
        dispatch_safety_status=payload.get("dispatch_safety_status"),
    )


def job_lifecycle(*, state_dir: Path, write_result: bool = True) -> dict[str, Any]:
    """Materialize and validate the current READY job without dispatching."""

    state_dir = Path(state_dir)
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    round_id = str(decision.get("round_id") or "")
    mainline = str(decision.get("mainline") or "")
    errors: list[str] = []
    warnings: list[str] = []

    try:
        from reverse_agent import project_jobs
    except Exception as exc:
        job_payload: dict[str, Any] = {}
        job_artifact_path = ""
        validation = {"validation_status": "FAILED", "errors": [str(exc)], "jobs": []}
        errors.append(f"project_jobs import failed: {exc}")
    else:
        job_payload = project_jobs.build_planned_job_payload(decision, status="READY")
        job_id = str(job_payload.get("job_id") or "")
        job_artifact_path = project_jobs.planned_job_artifact_path(job_id)
        if write_result and job_artifact_path:
            job_path = state_dir.parent / job_artifact_path
            job_path.parent.mkdir(parents=True, exist_ok=True)
            job_path.write_text(
                json.dumps(job_payload, ensure_ascii=True, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
        validation = project_jobs.validate_jobs_dir(state_dir)
        errors.extend(str(item) for item in validation.get("errors") or [])
        warnings.extend(str(item) for item in validation.get("warnings") or [])

    jobs = [job for job in validation.get("jobs") or [] if isinstance(job, dict)]
    current_jobs = [
        job for job in jobs
        if str(job.get("decision_id") or "") == decision_id
        and str(job.get("round_id") or "") == round_id
    ]
    current_ready = [
        job for job in current_jobs
        if str(job.get("status") or "") == "READY"
        and str(job.get("job_id") or "") == str(job_payload.get("job_id") or "")
    ]
    running_jobs = [
        job for job in jobs
        if str(job.get("status") or "") in {"RUNNING", "MANUAL_DISPATCHED"}
    ]
    if len(running_jobs) > 1:
        errors.append("more than one active/running job exists")
    if not current_ready:
        errors.append("current READY job artifact is missing or invalid")
    if validation.get("dispatch_enabled") is not False:
        errors.append("jobs validation reports dispatch enabled")

    gate_status = "PASSED" if not errors and validation.get("validation_status") == "PASSED" else "FAILED"
    generated_artifacts = [
        JOB_LIFECYCLE_VALIDATION_OUTPUT_PATH,
        JOB_LIFECYCLE_SNAPSHOT_OUTPUT_PATH,
    ]
    if job_artifact_path:
        generated_artifacts.append(job_artifact_path)
    result = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "artifact_name": JOB_LIFECYCLE_VALIDATION_RESULT_NAME,
        "gate_name": JOB_LIFECYCLE_NAME,
        "gate_status": gate_status,
        "decision_id": decision_id,
        "round_id": round_id,
        "mainline": mainline,
        "generated_at": _now_iso(),
        "job_id": job_payload.get("job_id"),
        "job_artifact_path": job_artifact_path,
        "job_status": job_payload.get("status"),
        "job_validation_status": validation.get("validation_status"),
        "job_count": validation.get("job_count"),
        "status_counts": validation.get("status_counts") or {},
        "current_ready_job_count": len(current_ready),
        "active_running_job_count": len(running_jobs),
        "validated_paths": validation.get("validated_paths") or [],
        "dispatch_enabled": False,
        "runner_dispatch": False,
        "model_api_invocation": False,
        "remote_mutation": False,
        "github_actions_dispatch": False,
        "sample_solving": False,
        "database_write": False,
        "errors": errors,
        "warnings": warnings,
        "generated_artifacts": generated_artifacts,
    }
    snapshot = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "artifact_name": JOB_LIFECYCLE_SNAPSHOT_NAME,
        "gate_name": JOB_LIFECYCLE_NAME,
        "decision_id": decision_id,
        "round_id": round_id,
        "generated_at": result["generated_at"],
        "job_artifact_path": job_artifact_path,
        "job_payload": job_payload,
        "validation": validation,
        "non_dispatching": True,
    }
    if write_result:
        gates_dir = state_dir / "gates"
        gates_dir.mkdir(parents=True, exist_ok=True)
        (gates_dir / JOB_LIFECYCLE_VALIDATION_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        (gates_dir / JOB_LIFECYCLE_SNAPSHOT_NAME).write_text(
            json.dumps(snapshot, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
    return result


def _job_lifecycle_gate_check(
    *,
    state_dir: Path,
    decision_id: str,
    round_id: str,
    decision_contract: dict[str, Any],
) -> dict[str, Any]:
    required = bool(
        decision_contract.get("accepted_requires_ready_job_contract_materialized")
        or decision_contract.get("accepted_requires_job_lifecycle_validation_gate")
    )
    payload = _read_json(state_dir / "gates" / JOB_LIFECYCLE_VALIDATION_RESULT_NAME)
    if not payload:
        return _check(
            "job_lifecycle_gate_artifact",
            "FAIL" if required else "PASS",
            "job lifecycle validation artifact is missing"
            if required
            else "job lifecycle validation artifact not required",
            required=required,
            artifact=JOB_LIFECYCLE_VALIDATION_OUTPUT_PATH,
        )
    errors: list[str] = []
    if str(payload.get("decision_id") or "") != decision_id:
        errors.append("decision_id mismatch")
    if str(payload.get("round_id") or "") != round_id:
        errors.append("round_id mismatch")
    if errors and not required:
        return _check(
            "job_lifecycle_gate_artifact",
            "PASS",
            "job lifecycle artifact is stale and not required for this decision",
            required=False,
            errors=errors,
        )
    if str(payload.get("gate_status") or "") != "PASSED":
        errors.append("gate_status is not PASSED")
    if str(payload.get("job_validation_status") or "") != "PASSED":
        errors.append("job_validation_status is not PASSED")
    if str(payload.get("job_status") or "") != "READY":
        errors.append("current job is not READY")
    if int(payload.get("current_ready_job_count") or 0) != 1:
        errors.append("current_ready_job_count is not 1")
    for field in (
        "dispatch_enabled",
        "runner_dispatch",
        "model_api_invocation",
        "remote_mutation",
        "github_actions_dispatch",
        "sample_solving",
        "database_write",
    ):
        if payload.get(field) is not False:
            errors.append(f"{field} is not false")
    ok = not errors
    return _check(
        "job_lifecycle_gate_artifact",
        "PASS" if ok else "FAIL",
        "job lifecycle validation is current, READY, and non-dispatching"
        if ok
        else "job lifecycle validation is missing required non-dispatching evidence",
        required=required,
        artifact=JOB_LIFECYCLE_VALIDATION_OUTPUT_PATH,
        job_artifact_path=payload.get("job_artifact_path"),
        job_id=payload.get("job_id"),
        job_status=payload.get("job_status"),
        errors=errors,
    )


def job_orchestration(*, state_dir: Path, write_result: bool = True) -> dict[str, Any]:
    """Generate a deterministic local job plan without dispatching it."""

    state_dir = Path(state_dir)
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    round_id = str(decision.get("round_id") or "")
    mainline = str(decision.get("mainline") or "")

    errors: list[str] = []
    warnings: list[str] = []
    generated_artifacts = [JOB_ORCHESTRATION_OUTPUT_PATH]
    try:
        from reverse_agent import project_jobs
    except Exception as exc:
        job_payload: dict[str, Any] = {}
        job_validation = {"validation_status": "FAILED", "errors": [str(exc)]}
        inventory = {"validation_status": "FAILED", "job_count": 0, "jobs": []}
        job_artifact_path = ""
        errors.append(f"project_jobs import failed: {exc}")
    else:
        job_payload = project_jobs.build_planned_job_payload(decision)
        job_id = str(job_payload.get("job_id") or "")
        job_artifact_path = project_jobs.planned_job_artifact_path(job_id)
        generated_artifacts.append(job_artifact_path)
        job_validation = project_jobs.validate_job_payload(job_payload)
        errors.extend(str(item) for item in job_validation.get("errors") or [])
        warnings.extend(str(item) for item in job_validation.get("warnings") or [])
        if write_result and not errors:
            job_path = state_dir.parent / job_artifact_path
            job_path.parent.mkdir(parents=True, exist_ok=True)
            job_path.write_text(
                json.dumps(job_payload, ensure_ascii=True, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
        inventory = project_jobs.validate_jobs_dir(state_dir)
        errors.extend(str(item) for item in inventory.get("errors") or [])
        warnings.extend(str(item) for item in inventory.get("warnings") or [])

    dispatch_enabled = bool(
        (job_payload.get("runner") or {}).get("dispatch_enabled")
        if isinstance(job_payload.get("runner"), dict)
        else False
    )
    dispatch_safety_status = "FAILED" if dispatch_enabled else "PASSED"
    validation_status = str(job_validation.get("validation_status") or "FAILED")
    inventory_validation_status = str(inventory.get("validation_status") or "FAILED")
    gate_status = (
        "PASSED"
        if validation_status == "PASSED"
        and inventory_validation_status == "PASSED"
        and dispatch_safety_status == "PASSED"
        else "FAILED"
    )
    result = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "artifact_name": JOB_ORCHESTRATION_RESULT_NAME,
        "gate_name": JOB_ORCHESTRATION_NAME,
        "gate_status": gate_status,
        "decision_id": decision_id,
        "round_id": round_id,
        "mainline": mainline,
        "generated_at": _now_iso(),
        "job_id": str(job_payload.get("job_id") or ""),
        "job_status": str(job_payload.get("status") or ""),
        "job_artifact_path": job_artifact_path,
        "job_validation_status": validation_status,
        "jobs_inventory_validation_status": inventory_validation_status,
        "job_count": int(inventory.get("job_count") or 0),
        "status_counts": inventory.get("status_counts") or {},
        "validated_paths": sorted(
            _norm_path(path) for path in inventory.get("validated_paths") or []
        ),
        "dispatch_enabled": dispatch_enabled,
        "dispatch_safety_status": dispatch_safety_status,
        "orchestration_mode": "non_dispatching",
        "errors": errors,
        "warnings": warnings,
        "generated_artifacts": generated_artifacts,
    }
    if write_result:
        out_dir = state_dir / "gates"
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / JOB_ORCHESTRATION_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
    return result


def _job_orchestration_gate_check(
    *,
    state_dir: Path,
    decision_id: str,
    round_id: str,
    decision_contract: dict[str, Any],
) -> dict[str, Any]:
    required = bool(decision_contract.get("accepted_requires_job_orchestration_artifact"))
    path = state_dir / "gates" / JOB_ORCHESTRATION_RESULT_NAME
    payload = _read_json(path)
    if not payload:
        return _check(
            "job_orchestration_artifact",
            "FAIL" if required else "PASS",
            "job orchestration artifact is missing"
            if required
            else "job orchestration artifact not required and not present",
            required=required,
            artifact=JOB_ORCHESTRATION_OUTPUT_PATH,
        )

    errors: list[str] = []
    if str(payload.get("decision_id") or "") != decision_id:
        errors.append("decision_id mismatch")
    if str(payload.get("round_id") or "") != round_id:
        errors.append("round_id mismatch")
    if errors and not required:
        return _check(
            "job_orchestration_artifact",
            "PASS",
            "job orchestration artifact is stale and not required for this decision",
            required=required,
            artifact=JOB_ORCHESTRATION_OUTPUT_PATH,
            errors=errors,
            gate_status=payload.get("gate_status"),
            job_validation_status=payload.get("job_validation_status"),
        )
    if str(payload.get("gate_name") or "") != JOB_ORCHESTRATION_NAME:
        errors.append("gate_name mismatch")
    if str(payload.get("gate_status") or "") != "PASSED":
        errors.append("gate_status is not PASSED")
    if str(payload.get("job_validation_status") or "") != "PASSED":
        errors.append("job_validation_status is not PASSED")
    if str(payload.get("jobs_inventory_validation_status") or "") != "PASSED":
        errors.append("jobs_inventory_validation_status is not PASSED")
    if str(payload.get("dispatch_safety_status") or "") != "PASSED":
        errors.append("dispatch_safety_status is not PASSED")
    if payload.get("dispatch_enabled") is not False:
        errors.append("dispatch_enabled is not false")
    job_artifact_path = _norm_path(payload.get("job_artifact_path"))
    if not job_artifact_path:
        errors.append("job_artifact_path missing")
    elif not (state_dir.parent / job_artifact_path).exists():
        errors.append("job artifact file missing")
    if not str(payload.get("job_id") or "").startswith("job_"):
        errors.append("job_id is not a job_ id")
    if str(payload.get("job_status") or "") not in {"DRAFT", "READY"}:
        errors.append("job_status is not DRAFT or READY")
    if not isinstance(payload.get("status_counts"), dict):
        errors.append("status_counts is not an object")
    if not isinstance(payload.get("validated_paths"), list):
        errors.append("validated_paths is not a list")

    ok = not errors
    return _check(
        "job_orchestration_artifact",
        "PASS" if ok else "FAIL",
        "job orchestration artifact is current, validated, and non-dispatching"
        if ok
        else "job orchestration artifact is missing required current validation evidence",
        required=required,
        artifact=JOB_ORCHESTRATION_OUTPUT_PATH,
        errors=errors,
        gate_status=payload.get("gate_status"),
        job_id=payload.get("job_id"),
        job_status=payload.get("job_status"),
        job_artifact_path=payload.get("job_artifact_path"),
        job_validation_status=payload.get("job_validation_status"),
        jobs_inventory_validation_status=payload.get("jobs_inventory_validation_status"),
        dispatch_safety_status=payload.get("dispatch_safety_status"),
    )


def runner_contract(
    *,
    state_dir: Path,
    write_result: bool = True,
    repo_root: Path | None = None,
) -> dict[str, Any]:
    """Generate a non-executable future-runner contract from job and command-plan."""

    state_dir = Path(state_dir)
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    round_id = str(decision.get("round_id") or "")
    mainline = str(decision.get("mainline") or "")
    errors: list[str] = []
    warnings: list[str] = []

    try:
        from reverse_agent import project_jobs, project_runner_contract
    except Exception as exc:
        contract_payload: dict[str, Any] = {}
        validation = {"validation_status": "FAILED", "errors": [str(exc)]}
        errors.append(f"runner contract import failed: {exc}")
    else:
        expected_job_id = project_jobs.planned_job_id_for_round(round_id)
        job_artifact_path = project_jobs.planned_job_artifact_path(expected_job_id)
        job_path = state_dir.parent / job_artifact_path
        if not job_path.exists():
            job_orchestration(state_dir=state_dir, write_result=True)
        try:
            job_payload = project_jobs.load_job_file(job_path)
        except (OSError, json.JSONDecodeError, ValueError) as exc:
            job_payload = {}
            errors.append(f"job artifact load failed: {exc}")
        command_plan_payload = project_runner_contract.load_command_plan(state_dir)
        if not command_plan_payload:
            errors.append("command_plan artifact missing")
        contract_payload = project_runner_contract.build_runner_contract_payload(
            state_dir=state_dir,
            repo_root=repo_root or state_dir.parent,
            job_payload=job_payload,
            command_plan_payload=command_plan_payload,
            job_artifact_path=job_artifact_path,
        )
        validation = project_runner_contract.validate_runner_contract_payload(
            contract_payload,
            command_plan_payload=command_plan_payload,
            job_payload=job_payload,
        )
        errors.extend(str(item) for item in validation.get("errors") or [])
        warnings.extend(str(item) for item in validation.get("warnings") or [])

    validation_status = str(validation.get("validation_status") or "FAILED")
    gate_status = "PASSED" if validation_status == "PASSED" and not errors else "FAILED"
    result = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "artifact_name": RUNNER_CONTRACT_RESULT_NAME,
        "gate_name": RUNNER_CONTRACT_NAME,
        "gate_status": gate_status,
        "decision_id": decision_id,
        "round_id": round_id,
        "mainline": mainline,
        "generated_at": _now_iso(),
        "contract_id": contract_payload.get("contract_id"),
        "contract_status": contract_payload.get("contract_status"),
        "contract_validation_status": validation_status,
        "job_id": contract_payload.get("job_id"),
        "job_artifact_path": contract_payload.get("job_artifact_path"),
        "job_validation_status": contract_payload.get("job_validation_status"),
        "dispatch_enabled": contract_payload.get("dispatch_enabled"),
        "executable": contract_payload.get("executable"),
        "runner": contract_payload.get("runner") or {},
        "permissions": contract_payload.get("permissions") or {},
        "budgets": contract_payload.get("budgets") or {},
        "allowed_commands": contract_payload.get("allowed_commands") or [],
        "forbidden_commands": contract_payload.get("forbidden_commands") or [],
        "allowed_command_count": validation.get("allowed_command_count", 0),
        "forbidden_command_count": validation.get("forbidden_command_count", 0),
        "allowed_write_paths": contract_payload.get("allowed_write_paths") or [],
        "external_invocations": contract_payload.get("external_invocations") or {},
        "policy": contract_payload.get("policy") or {},
        "errors": errors,
        "warnings": warnings,
        "generated_artifacts": [RUNNER_CONTRACT_OUTPUT_PATH],
    }
    if write_result:
        out_dir = state_dir / "gates"
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / RUNNER_CONTRACT_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
    return result


def _runner_contract_gate_check(
    *,
    state_dir: Path,
    decision_id: str,
    round_id: str,
    decision_contract: dict[str, Any],
) -> dict[str, Any]:
    required = bool(decision_contract.get("accepted_requires_runner_contract_artifact"))
    path = state_dir / "gates" / RUNNER_CONTRACT_RESULT_NAME
    payload = _read_json(path)
    if not payload:
        return _check(
            "runner_contract_artifact",
            "FAIL" if required else "PASS",
            "runner contract artifact is missing"
            if required
            else "runner contract artifact not required and not present",
            required=required,
            artifact=RUNNER_CONTRACT_OUTPUT_PATH,
        )

    errors: list[str] = []
    if str(payload.get("decision_id") or "") != decision_id:
        errors.append("decision_id mismatch")
    if str(payload.get("round_id") or "") != round_id:
        errors.append("round_id mismatch")
    if errors and not required:
        return _check(
            "runner_contract_artifact",
            "PASS",
            "runner contract artifact is stale and not required for this decision",
            required=required,
            artifact=RUNNER_CONTRACT_OUTPUT_PATH,
            errors=errors,
            gate_status=payload.get("gate_status"),
            contract_validation_status=payload.get("contract_validation_status"),
        )
    if str(payload.get("gate_name") or "") != RUNNER_CONTRACT_NAME:
        errors.append("gate_name mismatch")
    if str(payload.get("gate_status") or "") != "PASSED":
        errors.append("gate_status is not PASSED")
    if str(payload.get("contract_validation_status") or "") != "PASSED":
        errors.append("contract_validation_status is not PASSED")
    if payload.get("dispatch_enabled") is not False:
        errors.append("dispatch_enabled is not false")
    if payload.get("executable") is not False:
        errors.append("executable is not false")
    if not isinstance(payload.get("allowed_commands"), list):
        errors.append("allowed_commands is not a list")
    if not isinstance(payload.get("forbidden_commands"), list):
        errors.append("forbidden_commands is not a list")
    if not isinstance(payload.get("allowed_write_paths"), list):
        errors.append("allowed_write_paths is not a list")
    external_invocations = (
        payload.get("external_invocations")
        if isinstance(payload.get("external_invocations"), dict)
        else {}
    )
    enabled_external = sorted(
        key for key, value in external_invocations.items() if value is not False
    )
    if enabled_external:
        errors.append(f"external invocations enabled: {enabled_external}")

    ok = not errors
    return _check(
        "runner_contract_artifact",
        "PASS" if ok else "FAIL",
        "runner contract artifact is current, non-executable, and command-plan bounded"
        if ok
        else "runner contract artifact is missing required current validation evidence",
        required=required,
        artifact=RUNNER_CONTRACT_OUTPUT_PATH,
        errors=errors,
        gate_status=payload.get("gate_status"),
        contract_id=payload.get("contract_id"),
        contract_validation_status=payload.get("contract_validation_status"),
        job_id=payload.get("job_id"),
        dispatch_enabled=payload.get("dispatch_enabled"),
        executable=payload.get("executable"),
        allowed_command_count=payload.get("allowed_command_count"),
        forbidden_command_count=payload.get("forbidden_command_count"),
    )


