# State file categories
_STATE_FILE_CATEGORIES = (
    "current_live_artifact",
    "round_archive_artifact",
    "legacy_compat_artifact",
    "candidate_legacy_artifact",
    "candidate_orphan_artifact",
    "unknown_requires_manual_review",
)


def _scan_live_state_files(state_dir: Path, repo_root: Path) -> list[dict[str, Any]]:
    """Scan bounded live state files for hygiene inventory.

    Only inspects:
    - project_state/ immediate files (*.json, *.md, *.txt)
    - project_state/gates/ immediate JSON files
    Does NOT recursively scan project_state/rounds/ or solve_reports/.
    """
    entries: list[dict[str, Any]] = []
    # project_state/ immediate files
    for child in sorted(state_dir.iterdir()):
        if child.is_file() and child.suffix in (".json", ".md", ".txt"):
            rel = str(child.relative_to(repo_root)).replace("\\", "/")
            entries.append({"path": rel, "basename": child.name, "location": "project_state_root"})
    # project_state/gates/ immediate JSON files
    gates_dir = state_dir / "gates"
    if gates_dir.is_dir():
        for child in sorted(gates_dir.iterdir()):
            if child.is_file() and child.suffix == ".json":
                rel = str(child.relative_to(repo_root)).replace("\\", "/")
                entries.append({"path": rel, "basename": child.name, "location": "project_state_gates"})
    return entries


def _scan_bounded_archive_dirs(state_dir: Path, repo_root: Path, bounded_archive_dirs: list[str]) -> list[dict[str, Any]]:
    """Scan bounded archive directories for hygiene inventory.

    Only inspects the explicitly listed archive directories from the
    decision contract. Does NOT recursively scan project_state/rounds/.
    """
    entries: list[dict[str, Any]] = []
    for archive_dir_rel in bounded_archive_dirs:
        archive_dir = repo_root / archive_dir_rel
        if not archive_dir.is_dir():
            continue
        round_dir_name = archive_dir.name
        for child in sorted(archive_dir.iterdir()):
            if child.is_file():
                rel = str(child.relative_to(repo_root)).replace("\\", "/")
                entries.append({
                    "path": rel,
                    "basename": child.name,
                    "location": f"project_state_rounds_{round_dir_name}",
                })
    return entries


def _classify_state_file(
    path: str,
    basename: str,
    location: str,
    *,
    allowed_state_artifacts: set[str],
    current_round_id: str,
) -> str:
    """Classify a state file into one of the approved categories."""
    # Round archive files
    if "/rounds/" in path:
        return "round_archive_artifact"
    # Codex-named files that are current live artifacts
    codex_named_live = {
        "project_state/codex_execution_report.md",
        "project_state/gates/codex_report_auto_summary.json",
    }
    if path in codex_named_live:
        return "legacy_compat_artifact"
    # Check if it's an explicitly allowed state artifact
    if path in allowed_state_artifacts:
        return "current_live_artifact"
    # Known gate artifacts that are current
    known_gate_artifacts = {
        "command_plan.json", "execution_log.json", "final_gate_result.json",
        "gate_profile_plan.json", "phase1_completion_result.json",
        "policy_impact_audit.json", "policy_lint_result.json",
        "preflight_result.json", "report_summary_synthesis.json",
        "round_baseline.json", "round_close_snapshot.json",
        "round_delta_summary.json", "run_closeout_execution_log.json",
        "run_closeout_result.json", "run_round_result.json",
        "execute_decision_result.json",
        "jobs_inventory_result.json", "job_orchestration_result.json",
        "runner_contract_result.json", "audit_inventory_result.json",
        "naming_migration_plan.json", "state_hygiene_inventory.json",
        "user_solve_layer_result.json",
        "user_solve_trace_fallback_result.json",
        "user_solve_session_bundle_result.json",
    }
    if location == "project_state_gates" and basename in known_gate_artifacts:
        return "current_live_artifact"
    # Root-level known artifacts
    known_root_artifacts = {
        "pytest_result.txt",
    }
    if location == "project_state_root" and basename in known_root_artifacts:
        return "current_live_artifact"
    # Decision packet
    if basename == "decision_packet.md":
        return "current_live_artifact"
    # Unknown
    return "unknown_requires_manual_review"


def naming_hygiene(*, state_dir: Path, repo_root: Path | None = None, write_result: bool = True) -> dict[str, Any]:
    """Generate naming migration plan and state hygiene inventory.

    This command records the current neutral-primary migration state. It does
    NOT rename or delete legacy artifacts. It produces two gate artifacts:
    - naming_migration_plan.json
    - state_hygiene_inventory.json
    """
    if repo_root is None:
        repo_root = _derive_repo_root(state_dir)
    state_dir = Path(state_dir).resolve()
    repo_root = Path(repo_root).resolve()
    gates_dir = state_dir / "gates"
    gates_dir.mkdir(parents=True, exist_ok=True)

    # Read current decision context
    decision_meta = read_decision_meta(state_dir) or {}
    decision_id = decision_meta.get("decision_id", "")
    round_id = decision_meta.get("round_id", "")
    neutral_report_exists = (state_dir / NEUTRAL_EXECUTION_REPORT_NAME).exists()
    legacy_report_exists = (state_dir / LEGACY_EXECUTION_REPORT_NAME).exists()
    neutral_auto_exists = (gates_dir / NEUTRAL_REPORT_AUTO_SUMMARY_RESULT_NAME).exists()
    legacy_auto_exists = (gates_dir / REPORT_AUTO_SUMMARY_RESULT_NAME).exists()

    # Read allowed state artifacts and bounded archive dirs from decision contract
    # Use extract_markdown_json_block directly to avoid field-stripping in
    # read_decision_contract(), which does not yet know about these fields.
    _dc_block = extract_markdown_json_block(
        (state_dir / "decision_packet.md").read_text(encoding="utf-8"),
        "decision_contract",
    )
    if _dc_block.get("found") and not _dc_block.get("parse_error"):
        allowed_state_artifacts = set(
            v for v in (_dc_block.get("allowed_state_artifacts") or []) if isinstance(v, str)
        )
        bounded_archive_dirs = [
            v for v in (_dc_block.get("bounded_archive_dirs_to_inventory") or []) if isinstance(v, str)
        ]
    else:
        allowed_state_artifacts = set()
        bounded_archive_dirs = []

    # --- Build naming migration plan ---
    naming_entries: list[dict[str, Any]] = []
    for item in _CODEX_BOUND_NAMES:
        naming_entries.append({
            "current_name": item["current_name"],
            "current_path": item["current_path"],
            "scope": item["scope"],
            "classification": item["classification"],
            "proposed_neutral_name": item["proposed_neutral_name"],
            "proposed_neutral_path": item["proposed_neutral_path"],
            "compat_strategy": item["compat_strategy"],
            "action_this_round": "neutral_primary_with_legacy_alias",
            "migration_round": round_id or "current_round",
            "notes": (
                f"Identified as {item['classification']}. Neutral primary "
                f"{item['proposed_neutral_name']} is activated where supported. "
                f"Legacy {item['current_name']} remains a compatibility alias; "
                "no rename or deletion performed in this round."
            ),
        })

    # Also scan code for Codex-bound references
    code_refs: list[dict[str, str]] = []
    source_file = repo_root / "reverse_agent" / "project_gate.py"
    if source_file.exists():
        source_text = source_file.read_text(encoding="utf-8")
        for pattern_name in ["codex_execution_report", "codex_report_summary", "codex_report_auto_summary"]:
            count = source_text.lower().count(pattern_name.lower())
            if count > 0:
                code_refs.append({
                    "name": pattern_name,
                    "file": "reverse_agent/project_gate.py",
                    "occurrence_count": str(count),
                    "classification": "legacy_compat_reference",
                    "notes": f"Code reference to '{pattern_name}' found {count} time(s). Keep as legacy compatibility while neutral primary paths are active.",
                })
    test_file = repo_root / "tests" / "test_project_gate.py"
    if test_file.exists():
        test_text = test_file.read_text(encoding="utf-8")
        for pattern_name in ["codex_execution_report", "codex_report_summary", "codex_report_auto_summary"]:
            count = test_text.lower().count(pattern_name.lower())
            if count > 0:
                code_refs.append({
                    "name": pattern_name,
                    "file": "tests/test_project_gate.py",
                    "occurrence_count": str(count),
                    "classification": "legacy_compat_reference",
                    "notes": f"Test reference to '{pattern_name}' found {count} time(s). Keep as legacy compatibility while neutral primary paths are active.",
                })

    naming_plan = {
        "schema_version": 1,
        "plan_name": "naming-migration-plan",
        "decision_id": decision_id,
        "round_id": round_id,
        "generated_at": _now_iso(),
        "action_this_round": "neutral_primary_with_legacy_alias",
        "no_rename": True,
        "no_delete": True,
        "no_neutral_live_path_created": not neutral_report_exists,
        "neutral_live_path_created": neutral_report_exists,
        "legacy_alias_retained": legacy_report_exists,
        "neutral_auto_summary_created": neutral_auto_exists,
        "legacy_auto_summary_alias_retained": legacy_auto_exists,
        "codex_bound_names": naming_entries,
        "code_references": code_refs,
        "migration_strategy": (
            "Neutral report and auto-summary paths are primary for this round. "
            "Legacy Codex-named paths remain as compatibility aliases. "
            "No legacy file is renamed or deleted in this round."
        ),
    }

    # --- Build state hygiene inventory ---
    live_files = _scan_live_state_files(state_dir, repo_root)
    archive_files = _scan_bounded_archive_dirs(state_dir, repo_root, bounded_archive_dirs)
    inventory_entries: list[dict[str, Any]] = []
    for f in live_files + archive_files:
        category = _classify_state_file(
            f["path"], f["basename"], f["location"],
            allowed_state_artifacts=allowed_state_artifacts,
            current_round_id=round_id,
        )
        # Determine referenced_by
        referenced_by: list[str] = []
        if category == "current_live_artifact":
            referenced_by.append("gate_pipeline")
        if category == "round_archive_artifact":
            referenced_by.append("round_archive")
        if f["basename"] in ("codex_execution_report.md", "codex_report_auto_summary.json"):
            referenced_by.append("codex_naming_convention")

        # Determine freshness_basis
        if category == "round_archive_artifact":
            freshness_basis = "round_archive"
        elif category in ("current_live_artifact", "legacy_compat_artifact"):
            freshness_basis = "current_round"
        else:
            freshness_basis = "unknown"

        entry: dict[str, Any] = {
            "path": f["path"],
            "category": category,
            "referenced_by": referenced_by,
            "freshness_basis": freshness_basis,
            "safe_to_delete": False,
            "delete_reason": "Deletion explicitly deferred; no file may be deleted in this round",
            "notes": "",
        }
        # Add migration_target for Codex-named files
        for item in _CODEX_BOUND_NAMES:
            if f["path"] == item.get("current_path", "").split(" ")[0] and f["path"].startswith("project_state/"):
                entry["migration_target"] = item["proposed_neutral_path"]
                entry["notes"] = f"Codex-bound name; proposed neutral: {item['proposed_neutral_name']}"
                break
        inventory_entries.append(entry)

    inventory = {
        "schema_version": 1,
        "plan_name": "state-hygiene-inventory",
        "decision_id": decision_id,
        "round_id": round_id,
        "generated_at": _now_iso(),
        "no_rename": True,
        "no_delete": True,
        "no_neutral_live_path_created": not neutral_report_exists,
        "neutral_live_path_created": neutral_report_exists,
        "legacy_alias_retained": legacy_report_exists,
        "scan_scope": (
            "project_state/ immediate files, project_state/gates/ immediate JSON files, "
            "and bounded archive directories from decision_contract.bounded_archive_dirs_to_inventory. "
            "No recursive scan of project_state/rounds/ or solve_reports/."
        ),
        "bounded_archive_dirs": bounded_archive_dirs,
        "entries": inventory_entries,
    }

    # Write artifacts
    if write_result:
        (gates_dir / _NAMING_MIGRATION_PLAN_NAME).write_text(
            json.dumps(naming_plan, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
        )
        (gates_dir / _STATE_HYGIENE_INVENTORY_NAME).write_text(
            json.dumps(inventory, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
        )

    result: dict[str, Any] = {
        "schema_version": 1,
        "gate_name": "naming-hygiene",
        "gate_status": "PASSED",
        "decision_id": decision_id,
        "round_id": round_id,
        "generated_at": _now_iso(),
        "naming_migration_plan": f"project_state/gates/{_NAMING_MIGRATION_PLAN_NAME}",
        "state_hygiene_inventory": f"project_state/gates/{_STATE_HYGIENE_INVENTORY_NAME}",
        "codex_bound_name_count": len(naming_entries),
        "code_reference_count": len(code_refs),
        "state_file_count": len(inventory_entries),
        "archive_entry_count": len(archive_files),
        "no_rename": True,
        "no_delete": True,
        "no_neutral_live_path_created": not neutral_report_exists,
        "neutral_live_path_created": neutral_report_exists,
        "legacy_alias_retained": legacy_report_exists,
    }
    return result


def _print_naming_hygiene(result: dict[str, Any]) -> None:
    gate_status = result.get("gate_status", "UNKNOWN")
    print(f"naming-hygiene: {gate_status}")
    for key in ("decision_id", "round_id", "naming_migration_plan", "state_hygiene_inventory",
                "codex_bound_name_count", "code_reference_count", "state_file_count"):
        val = result.get(key)
        if val is not None:
            print(f"{key}: {val}")
    for flag in ("no_rename", "no_delete", "no_neutral_live_path_created"):
        if result.get(flag):
            print(f"{flag}: True")


def phase1_completion(
    *,
    state_dir: Path,
    repo_root: Path | None = None,
    write_result: bool = True,
) -> dict[str, Any]:
    """Generate a structured Phase 1 completion artifact.

    Checks 10 Phase 1 capabilities by verifying their evidence artifacts
    exist and are parseable.  Writes phase1_completion_result.json when
    write_result is True.
    """
    state_dir = Path(state_dir)
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    round_id = str(decision.get("round_id") or "")

    gates_dir = state_dir / "gates"

    capabilities: list[dict[str, Any]] = []
    warnings: list[str] = []
    blocking_reasons: list[str] = []

    cap_defs = [
        {
            "id": "command_plan_authority",
            "name": "Command Plan Authority",
            "evidence_path": f"project_state/gates/{COMMAND_PLAN_RESULT_NAME}",
            "relevant_tests": ["test_command_plan_*"],
            "notes": "Verifies command-plan gate generates and validates execution plans.",
        },
        {
            "id": "decision_command_plan_conflict_detection",
            "name": "Decision/Command-Plan Conflict Detection",
            "evidence_path": f"project_state/gates/{PREFLIGHT_RESULT_NAME}",
            "relevant_tests": ["test_decision_command_plan_conflict*"],
            "notes": "Verifies preflight detects conflicts between decision and command-plan.",
        },
        {
            "id": "policy_lint_prompt_consistency",
            "name": "Policy Lint Prompt Consistency",
            "evidence_path": f"project_state/gates/{POLICY_LINT_RESULT_NAME}",
            "relevant_tests": ["test_policy_lint*"],
            "notes": "Verifies policy-lint detects drift in skills, prompts, and docs.",
        },
        {
            "id": "execution_log_derivation",
            "name": "Execution Log Derivation",
            "evidence_path": f"project_state/gates/{EXECUTION_LOG_RESULT_NAME}",
            "relevant_tests": ["TestExecutionLogCurrentRoundFiltering"],
            "notes": "Verifies execution-log generates structured command evidence.",
        },
        {
            "id": "report_auto_summary_synthesis",
            "name": "Report Auto-Summary Synthesis",
            "evidence_path": f"project_state/gates/{REPORT_AUTO_SUMMARY_RESULT_NAME}",
            "relevant_tests": ["test_report_auto_summary*"],
            "notes": "Verifies report-auto-summary synthesizes codex report summary.",
        },
        {
            "id": "report_summary_synthesis",
            "name": "Report Summary Synthesis",
            "evidence_path": f"project_state/gates/{REPORT_SUMMARY_RESULT_NAME}",
            "relevant_tests": ["TestReportSummaryMismatchBlocking"],
            "notes": "Verifies report-summary synthesis and mismatch blocking.",
        },
        {
            "id": "final_check_hard_gate",
            "name": "Final Check Hard Gate",
            "evidence_path": f"project_state/gates/{FINAL_GATE_RESULT_NAME}",
            "relevant_tests": ["test_final_check*"],
            "notes": "Verifies final-check enforces hard gate constraints.",
        },
        {
            "id": "run_round_execute",
            "name": "Run-Round Execute",
            "evidence_path": f"project_state/gates/{RUN_ROUND_RESULT_NAME}",
            "relevant_tests": ["test_run_round*"],
            "notes": "Verifies run-round executes command-plan in dry-run and execute modes.",
        },
        {
            "id": "run_closeout_archive",
            "name": "Run-Closeout Archive",
            "evidence_path": f"project_state/gates/{RUN_CLOSEOUT_RESULT_NAME}",
            "relevant_tests": ["test_close_round*", "TestCloseoutExecutionLogFreshness"],
            "notes": "Verifies run-closeout executes bounded closeout and archives.",
        },
        {
            "id": "execute_decision_entrypoint",
            "name": "Execute-Decision Entrypoint",
            "evidence_paths": [
                f"project_state/gates/{EXECUTION_LOG_RESULT_NAME}",
                f"project_state/gates/{COMMAND_PLAN_RESULT_NAME}",
                f"project_state/gates/{RUN_ROUND_RESULT_NAME}",
            ],
            "relevant_tests": ["TestExecuteDecision*"],
            "notes": "Verifies execute-decision thin wrapper delegates to run-round. Evidence: execution-log records execute-decision commands, command-plan authorizes them, run-round-result shows execution outcome.",
        },
    ]

    for cap_def in cap_defs:
        cap = dict(cap_def)
        # Support both singular evidence_path and plural evidence_paths
        evidence_paths = cap_def.get("evidence_paths")
        if evidence_paths is None:
            ep = cap_def.get("evidence_path", "")
            evidence_paths = [ep] if ep else []
        # Also store singular evidence_path for backward compatibility
        if "evidence_path" not in cap and evidence_paths:
            cap["evidence_path"] = evidence_paths[0]
        cap["evidence_paths"] = evidence_paths

        all_exist = True
        missing: list[str] = []
        for ep in evidence_paths:
            evidence_file = gates_dir / Path(ep).name
            if evidence_file.exists():
                try:
                    json.loads(evidence_file.read_text(encoding="utf-8"))
                except (json.JSONDecodeError, ValueError):
                    all_exist = False
                    missing.append(f"{ep}: not valid JSON")
            else:
                all_exist = False
                missing.append(f"{ep}: not found")
        if all_exist:
            cap["status"] = "PASS"
        else:
            cap["status"] = "FAIL"
            blocking_reasons.append(f"{cap_def['id']}: evidence path check failed: {'; '.join(missing)}")
        capabilities.append(cap)

    overall_status = "PASS" if all(c.get("status") == "PASS" for c in capabilities) else "FAIL"

    result: dict[str, Any] = {
        "gate_name": PHASE1_COMPLETION_NAME,
        "gate_status": overall_status,
        "decision_id": decision_id,
        "round_id": round_id,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "capabilities": capabilities,
        "overall_status": overall_status,
        "warnings": warnings,
        "blocking_reasons": blocking_reasons,
    }

    if write_result:
        gates_dir.mkdir(parents=True, exist_ok=True)
        (gates_dir / PHASE1_COMPLETION_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2),
            encoding="utf-8",
            newline="\n",
        )

    return result


def run_closeout(
    *,
    state_dir: Path,
    round_id: str,
    repo_root: Path | None = None,
    command_runner: CommandRunner | None = None,
    write_result: bool = True,
    pytest_result_path: Path | None = None,
) -> dict[str, Any]:
    """Execute a bounded closeout sequence and record command evidence.

    Runs decision-lint, preflight, pytest, gate-profile, command-plan,
    report-summary, final-check, close-round, and a final after-close
    final-check. Each step is recorded into pytest_result.txt.
    """
    repo_root = repo_root or Path.cwd()
    state_dir = Path(state_dir)
    requested_round_id = str(round_id or "")

    # 1. Validate decision metadata and requested round_id
    decision = read_decision_meta(state_dir)
    decision_id = str(decision.get("decision_id") or "")
    decision_round_id = str(decision.get("round_id") or "")

    invalid_reasons: list[str] = []
    if not state_dir.exists() or not state_dir.is_dir():
        invalid_reasons.append(f"state_dir is not a directory: {state_dir}")
    if not requested_round_id:
        invalid_reasons.append("round_id is required")
    if decision_round_id and requested_round_id and requested_round_id != decision_round_id:
        invalid_reasons.append(
            f"round_id mismatch: requested={requested_round_id}, decision={decision_round_id}"
        )

    if invalid_reasons:
        result = {
            "schema_version": GATE_RESULT_SCHEMA_VERSION,
            "gate_name": RUN_CLOSEOUT_NAME,
            "closeout_status": "INVALID",
            "decision_id": decision_id,
            "round_id": requested_round_id,
            "generated_at": _now_iso(),
            "executed_steps": [],
            "skipped_steps": [],
            "blocking_reasons": invalid_reasons,
            "warnings": [],
            "recommended_next_action": "fix_run_closeout_invalid_args",
        }
        if write_result:
            out_dir = state_dir / "gates"
            out_dir.mkdir(parents=True, exist_ok=True)
            (out_dir / RUN_CLOSEOUT_RESULT_NAME).write_text(
                json.dumps(result, ensure_ascii=True, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
        return result

    _remove_current_round_close_snapshot(
        state_dir=state_dir,
        decision_id=decision_id,
        round_id=requested_round_id,
    )

    # 2. Generate or refresh command-plan before execution
    plan_result = command_plan(
        state_dir=state_dir,
        write_result=write_result,
        final_check_passed_override=True,
    )

    # 3. Build the bounded closeout step sequence
    steps = _build_closeout_steps(
        state_dir=state_dir,
        round_id=requested_round_id,
        plan_result=plan_result,
    )

    # 4. Initialize pytest_result.txt with a fresh current-round header.
    pytest_path = pytest_result_path or (state_dir / "pytest_result.txt")
    report_id = _expected_report_id(requested_round_id) if requested_round_id else ""
    run_closeout_command = (
        f"python -m reverse_agent.project_gate run-closeout "
        f"--state-dir {state_dir} --round-id {requested_round_id}"
    )
    runner = command_runner or (lambda command: _default_command_runner(command, cwd=repo_root))
    authorized_top_level_commands = {
        str(item.get("command") or "")
        for item in (plan_result.get("commands") or [])
        if isinstance(item, dict) and str(item.get("command") or "")
    }
    if write_result:
        out_dir = state_dir / "gates"
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / RUN_CLOSEOUT_RESULT_NAME).write_text(
            json.dumps(
                {
                    "schema_version": GATE_RESULT_SCHEMA_VERSION,
                    "gate_name": RUN_CLOSEOUT_NAME,
                    "closeout_status": "IN_PROGRESS",
                    "decision_id": decision_id,
                    "round_id": requested_round_id,
                    "generated_at": _now_iso(),
                    "executed_steps": [],
                    "skipped_steps": [],
                    "startup_blocks": [],
                    "close_round_result": None,
                    "blocking_reasons": [],
                    "warnings": [],
                    "recommended_next_action": "run_closeout_in_progress",
                },
                ensure_ascii=True,
                indent=2,
            )
            + "\n",
            encoding="utf-8",
            newline="\n",
        )
        _initialize_run_round_pytest_result(
            pytest_path,
            decision_id=decision_id,
            round_id=requested_round_id,
            command_plan_payload=plan_result,
        )
        _record_startup_diagnostics(
            pytest_path,
            repo_root=repo_root,
            runner=runner,
            state_dir=state_dir,
        )
        closeout_log_path = state_dir / "gates" / RUN_CLOSEOUT_EXECUTION_LOG_NAME
        closeout_log_path.write_text(
            json.dumps(
                {
                    "schema_version": 1,
                    "gate_name": RUN_CLOSEOUT_NAME,
                    "decision_id": decision_id,
                    "round_id": requested_round_id,
                    "command_blocks": [],
                },
                ensure_ascii=True,
                indent=2,
            )
            + "\n",
            encoding="utf-8",
            newline="\n",
        )
        stale_archive_dir = state_dir / "rounds" / requested_round_id
        if stale_archive_dir.exists():
            import shutil as _shutil
            _shutil.rmtree(stale_archive_dir)

    # 5. Execute closeout steps
    # Note: startup diagnostics are NOT recorded into top-level pytest_result.txt
    # by run_closeout. They are already present from the run-round --execute
    # phase. Closeout internal command evidence goes to the scoped
    # run_closeout_execution_log.json instead.
    def _record_top_level_if_authorized(
        *,
        command: str,
        stdout: str,
        stderr: str,
        exit_code: int,
    ) -> None:
        if not write_result or command not in authorized_top_level_commands:
            return
        _remove_pytest_command_blocks(pytest_path, command=command)
        _append_command_block_to_pytest_result(
            pytest_path,
            command=command,
            stdout=stdout,
            stderr=stderr,
            exit_code=exit_code,
        )

    # Record run-closeout self-invocation marker in the closeout log
    _append_command_block_to_closeout_log(
        state_dir,
        command=run_closeout_command,
        stdout=f"run-closeout: started for round {requested_round_id}",
        stderr="",
        exit_code=0,
        decision_id=decision_id,
        round_id=requested_round_id,
    )

    # 6. Execute steps
    executed_steps: list[dict[str, Any]] = []
    skipped_steps: list[dict[str, Any]] = []
    blocking_reasons: list[str] = []
    warnings: list[str] = []
    close_round_result: dict[str, Any] | None = None
    close_round_executed = False

    for step in steps:
        step_name = step["name"]
        command = step["command"]
        kind = step["kind"]
        expected = step["expected_exit_codes"]
        is_close_round = step["is_close_round"]

        # The final-check-after-close step is handled separately after
        # the after-close report refresh (line ~7713).  Skip it in the
        # main loop so its failure doesn't block the refresh.
        if step_name in {
            "final-check-after-close",
            "audit-readiness-packet-after-close",
            "final-check-after-audit-readiness",
        }:
            continue

        # Allowlist check
        if kind not in RUN_CLOSEOUT_ALLOWED_KINDS:
            skipped_steps.append({
                "name": step_name,
                "command": command,
                "kind": kind,
                "reason": f"kind {kind!r} not in run-closeout allowlist",
            })
            blocking_reasons.append(f"step {step_name} refused: kind {kind!r} not in allowlist")
            break

        # Close-round: call close_round() directly so it owns its command block
        if is_close_round:
            # Remove any stale round archive before refreshing report/synthesis
            # evidence.  If the stale archive is still present during report
            # refresh, archive paths are claimed in the live report and then
            # disappear before close_round() validates the synthesis.
            _archive_dir = state_dir / "rounds" / requested_round_id
            if _archive_dir.exists():
                import shutil as _shutil
                _shutil.rmtree(_archive_dir)
            execution_log(state_dir=state_dir, write_result=True)
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
            build_report_summary_synthesis(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            close_round_result = close_round(
                state_dir=state_dir,
                round_id=requested_round_id,
                repo_root=repo_root,
            )
            close_status = str(close_round_result.get("close_status") or "")
            close_exit_code = _close_round_exit_code(close_status)
            close_stdout = _close_round_output_text(close_round_result)
            _append_command_block_to_closeout_log(
                state_dir,
                command=command,
                stdout=close_stdout,
                stderr="",
                exit_code=close_exit_code,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            _record_top_level_if_authorized(
                command=command,
                stdout=close_stdout,
                stderr="",
                exit_code=close_exit_code,
            )
            executed_steps.append({
                "name": step_name,
                "command": command,
                "kind": kind,
                "expected_exit_codes": expected,
                "exit_code": close_exit_code,
                "status": "PASSED" if close_exit_code in expected else "FAILED",
            })
            close_round_executed = True
            if close_exit_code not in expected:
                blocking_reasons.append(
                    f"step {step_name} exited {close_exit_code}, expected {expected}: close_status={close_status}"
                )
                break
            continue

        # Gate steps: call functions directly so their output is authoritative
        step_exit_code = 0
        step_stdout = ""
        step_stderr = ""
        if kind == "decision-lint":
            lint_result = lint_decision(state_dir)
            step_exit_code = 0 if not lint_result.get("errors") else 1
            step_stdout = json.dumps(lint_result, ensure_ascii=True, indent=2)
        elif kind == "preflight":
            pf_result = preflight(state_dir=state_dir, write_result=True, allow_consumed=True)
            pf_status = str(pf_result.get("gate_status") or "")
            step_exit_code = _preflight_exit_code(pf_status)
            step_stdout = f"preflight: {pf_status}"
        elif kind == "pytest":
            proc = runner(command)
            step_exit_code = proc.returncode
            step_stdout = proc.stdout or ""
            step_stderr = proc.stderr or ""
        elif kind == "gate-profile":
            gp_result = gate_profile(state_dir=state_dir, write_result=True)
            gp_status = str(gp_result.get("gate_status") or "")
            step_exit_code = 0 if gp_status == "PASSED" else 1
            step_stdout = json.dumps(gp_result, ensure_ascii=True, indent=2)
        elif kind == "command-plan":
            cp_result = command_plan(
                state_dir=state_dir,
                write_result=True,
                final_check_passed_override=True,
            )
            cp_status = str(cp_result.get("plan_status") or "")
            step_exit_code = 0 if cp_status == "PASSED" else 1
            if step_name == "command-plan-json":
                # Record the JSON output for the --json variant
                step_stdout = json.dumps(cp_result, ensure_ascii=True, indent=2)
            else:
                step_stdout = f"command-plan: {cp_status}"
        elif kind == "doctor":
            proc = runner(command)
            step_exit_code = proc.returncode
            step_stdout = (
                f"doctor diagnostic completed with exit {step_exit_code}; "
                "command-plan permits [0, 1] and governance-fix records backlog split evidence."
            )
            step_stderr = proc.stderr or ""
        elif kind == "audit-inventory":
            ai_result = audit_inventory(state_dir=state_dir, write_result=True)
            ai_status = str(ai_result.get("gate_status") or "")
            step_exit_code = 0 if ai_status == "PASSED" else 1
            step_stdout = (
                f"audit-inventory: {ai_status}\n"
                f"decision_id: {ai_result.get('decision_id')}\n"
                f"round_id: {ai_result.get('round_id')}\n"
                f"inventory_validation_status: {ai_result.get('inventory_validation_status')}\n"
                f"audit_count: {ai_result.get('audit_count')}\n"
                f"artifact: {AUDIT_INVENTORY_OUTPUT_PATH}"
            )
        elif kind == "jobs-inventory":
            ji_result = jobs_inventory(state_dir=state_dir, write_result=True)
            ji_status = str(ji_result.get("gate_status") or "")
            step_exit_code = 0 if ji_status == "PASSED" else 1
            step_stdout = (
                f"jobs-inventory: {ji_status}\n"
                f"decision_id: {ji_result.get('decision_id')}\n"
                f"round_id: {ji_result.get('round_id')}\n"
                f"inventory_validation_status: {ji_result.get('inventory_validation_status')}\n"
                f"job_count: {ji_result.get('job_count')}\n"
                f"artifact: {JOBS_INVENTORY_OUTPUT_PATH}"
            )
        elif kind == "post-final-evidence-sync":
            pfs_result = post_final_evidence_sync(state_dir=state_dir, write_result=True)
            pfs_status = str(pfs_result.get("gate_status") or "")
            step_exit_code = 0 if pfs_status == "PASSED" else 1
            step_stdout = json.dumps(pfs_result, ensure_ascii=True, indent=2)
        elif kind == "job-lifecycle":
            jl_result = job_lifecycle(state_dir=state_dir, write_result=True)
            jl_status = str(jl_result.get("gate_status") or "")
            step_exit_code = 0 if jl_status == "PASSED" else 1
            step_stdout = json.dumps(jl_result, ensure_ascii=True, indent=2)
        elif kind == "job-orchestration":
            jo_result = job_orchestration(state_dir=state_dir, write_result=True)
            jo_status = str(jo_result.get("gate_status") or "")
            step_exit_code = 0 if jo_status == "PASSED" else 1
            step_stdout = json.dumps(jo_result, ensure_ascii=True, indent=2)
        elif kind == "runner-contract":
            rc_result = runner_contract(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            rc_status = str(rc_result.get("gate_status") or "")
            step_exit_code = 0 if rc_status == "PASSED" else 1
            step_stdout = json.dumps(rc_result, ensure_ascii=True, indent=2)
        elif kind == "agent-runner-dry-run":
            ar_result = agent_runner_dry_run(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            ar_status = str(ar_result.get("gate_status") or "")
            step_exit_code = 0 if ar_status == "PASSED" else 1
            step_stdout = json.dumps(ar_result, ensure_ascii=True, indent=2)
        elif kind == "agent-runner-handoff-bundle":
            hb_result = agent_runner_handoff_bundle(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            hb_status = str(hb_result.get("gate_status") or "")
            step_exit_code = 0 if hb_status == "PASSED" else 1
            step_stdout = json.dumps(hb_result, ensure_ascii=True, indent=2)
        elif kind == "agent-runner-handoff-validate":
            hv_result = agent_runner_handoff_validate(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            hv_status = str(hv_result.get("gate_status") or "")
            step_exit_code = 0 if hv_status == "PASSED" else 1
            step_stdout = json.dumps(hv_result, ensure_ascii=True, indent=2)
        elif kind == "startup-snapshot":
            ss_result = startup_snapshot(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            ss_status = str(ss_result.get("gate_status") or "")
            step_exit_code = 0 if ss_status == "PASSED" else 1
            step_stdout = json.dumps(ss_result, ensure_ascii=True, indent=2)
        elif kind == "control-plane-snapshot":
            cps_result = control_plane_snapshot(
                state_dir=state_dir,
                write_result=True,
                final_state="--final-state" in command,
            )
            cps_status = str(cps_result.get("gate_status") or "")
            step_exit_code = 0 if cps_status == "PASSED" else 1
            step_stdout = json.dumps(cps_result, ensure_ascii=True, indent=2)
        elif kind == "report-summary":
            rs_result = build_report_summary_synthesis(
                state_dir=state_dir, repo_root=repo_root, write_result=True
            )
            rs_status = str(rs_result.get("synthesis_status") or "")
            step_exit_code = 0 if rs_status == "PASSED" else 1
            step_stdout = json.dumps(rs_result, ensure_ascii=True, indent=2)
        elif kind == "execute-decision":
            ed_result = execute_decision(
                state_dir=state_dir,
                round_id=requested_round_id,
                dry_run=True,
                repo_root=repo_root,
                command_runner=command_runner,
                write_result=False,
                pytest_result_path=None,
                allow_consumed_preflight=True,
            )
            (state_dir / "gates" / EXECUTE_DECISION_RESULT_NAME).write_text(
                json.dumps(ed_result, ensure_ascii=True, indent=2) + "\n",
                encoding="utf-8",
                newline="\n",
            )
            ed_status = str(ed_result.get("gate_status") or ed_result.get("status") or "")
            step_exit_code = 0 if ed_status == "PASSED" else 1
            step_stdout = (
                f"execute-decision: {ed_status}\n"
                f"decision_id: {ed_result.get('decision_id')}\n"
                f"round_id: {ed_result.get('round_id')}\n"
                f"mode: {ed_result.get('mode')}\n"
                "closeout_execution_mode: non_recursive_plan_validation\n"
                f"artifact: {EXECUTE_DECISION_OUTPUT_PATH}"
            )
        elif kind == "execution-log":
            el_result = execution_log(state_dir=state_dir, write_result=True)
            el_status = str(el_result.get("gate_status") or "")
            step_exit_code = 0 if el_status == "PASSED" else 1
            step_stdout = (
                f"execution-log: {el_status}\n"
                f"decision_id: {el_result.get('decision_id')}\n"
                f"round_id: {el_result.get('round_id')}\n"
                f"source: {el_result.get('source')}\n"
                f"artifact: {EXECUTION_LOG_OUTPUT_PATH}\n"
                f"recommended_next_action: {el_result.get('recommended_next_action') or 'no_action_required'}"
            )
        elif kind == "audit-readiness-packet":
            ar_result = audit_readiness_packet(state_dir=state_dir, write_result=True)
            ar_status = str(ar_result.get("gate_status") or "")
            step_exit_code = 0 if ar_status == "PASSED" else 1
            step_stdout = (
                f"audit-readiness-packet: {ar_status}\n"
                f"decision_id: {ar_result.get('decision_id')}\n"
                f"round_id: {ar_result.get('round_id')}\n"
                f"readiness_status: {ar_result.get('readiness_status')}\n"
                f"artifact: {AUDIT_READINESS_PACKET_OUTPUT_PATH}"
            )
        elif kind == "current-handoff-packet":
            ch_result = current_handoff_packet(state_dir=state_dir, write_result=True)
            ch_status = str(ch_result.get("gate_status") or "")
            step_exit_code = 0 if ch_status == "PASSED" else 1
            step_stdout = (
                f"current-handoff-packet: {ch_status}\n"
                f"decision_id: {ch_result.get('decision_id')}\n"
                f"round_id: {ch_result.get('round_id')}\n"
                f"report_id: {ch_result.get('report_id')}\n"
                f"artifact: {CURRENT_HANDOFF_PACKET_OUTPUT_PATH}"
            )
        elif kind == "local-execution-bundle":
            leb_result = local_execution_bundle(state_dir=state_dir, write_result=True)
            leb_status = str(leb_result.get("gate_status") or "")
            step_exit_code = 0 if leb_status == "PASSED" else 1
            step_stdout = (
                f"local-execution-bundle: {leb_status}\n"
                f"decision_id: {leb_result.get('decision_id')}\n"
                f"round_id: {leb_result.get('round_id')}\n"
                f"report_id: {leb_result.get('report_id')}\n"
                f"artifact: {LOCAL_EXECUTION_BUNDLE_OUTPUT_PATH}"
            )
        elif kind == "codex-prompt-packet":
            cpp_result = codex_prompt_packet(state_dir=state_dir, write_result=True)
            cpp_status = str(cpp_result.get("gate_status") or "")
            step_exit_code = 0 if cpp_status == "PASSED" else 1
            step_stdout = (
                f"codex-prompt-packet: {cpp_status}\n"
                f"decision_id: {cpp_result.get('decision_id')}\n"
                f"round_id: {cpp_result.get('round_id')}\n"
                f"report_id: {cpp_result.get('report_id')}\n"
                f"artifact: {CODEX_PROMPT_PACKET_OUTPUT_PATH}"
            )
        elif kind == "audit-precheck":
            ap_result = audit_precheck(state_dir=state_dir, write_result=True)
            ap_status = str(ap_result.get("gate_status") or "")
            step_exit_code = 0 if ap_status == "PASSED" else 1
            step_stdout = (
                f"audit-precheck: {ap_status}\n"
                f"decision_id: {ap_result.get('decision_id')}\n"
                f"round_id: {ap_result.get('round_id')}\n"
                f"report_id: {ap_result.get('report_id')}\n"
                f"audit_recommendation: {ap_result.get('audit_recommendation')}\n"
                f"artifact: {AUDIT_PRECHECK_OUTPUT_PATH}"
            )
        elif kind == "ci-workflow-coverage":
            cw_result = ci_workflow_coverage(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            cw_status = str(cw_result.get("gate_status") or "")
            step_exit_code = 0 if cw_status == "PASSED" else 1
            step_stdout = (
                f"ci-workflow-coverage: {cw_status}\n"
                f"decision_id: {cw_result.get('decision_id')}\n"
                f"round_id: {cw_result.get('round_id')}\n"
                f"report_id: {cw_result.get('report_id')}\n"
                f"recommendation: {cw_result.get('recommendation')}\n"
                f"missing_coverage: {len(cw_result.get('missing_coverage') or [])}\n"
                f"unsafe_patterns_found: {len(cw_result.get('unsafe_patterns_found') or [])}\n"
                f"artifact: {CI_WORKFLOW_COVERAGE_OUTPUT_PATH}"
            )
        elif kind == "ci-workflow-readiness":
            cwr_result = ci_workflow_readiness(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            cwr_status = str(cwr_result.get("gate_status") or "")
            step_exit_code = 0 if cwr_status == "PASSED" else 1
            step_stdout = (
                f"ci-workflow-readiness: {cwr_status}\n"
                f"decision_id: {cwr_result.get('decision_id')}\n"
                f"round_id: {cwr_result.get('round_id')}\n"
                f"report_id: {cwr_result.get('report_id')}\n"
                f"readiness_status: {cwr_result.get('readiness_status')}\n"
                f"missing_coverage: {len(cwr_result.get('missing_coverage') or [])}\n"
                f"unsafe_patterns_found: {len(cwr_result.get('unsafe_patterns_found') or [])}\n"
                f"artifact: {CI_WORKFLOW_READINESS_OUTPUT_PATH}"
            )
        elif kind == "decision-preflight":
            dp_result = decision_preflight(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            dp_status = str(dp_result.get("gate_status") or "")
            step_exit_code = 0 if dp_status == "PASSED" else 1
            step_stdout = json.dumps(dp_result, ensure_ascii=True, indent=2)
        elif kind == "ci-run-evidence":
            cre_result = ci_run_evidence(
                state_dir=state_dir,
                write_result=True,
            )
            cre_status = str(cre_result.get("gate_status") or "")
            step_exit_code = 0 if cre_status == "PASSED" else 1
            step_stdout = (
                f"ci-run-evidence: {cre_status}\n"
                f"decision_id: {cre_result.get('decision_id')}\n"
                f"round_id: {cre_result.get('round_id')}\n"
                f"report_id: {cre_result.get('report_id')}\n"
                f"ci_observation_status: {cre_result.get('ci_observation_status')}\n"
                f"snapshot_validation_status: {cre_result.get('snapshot_validation_status')}\n"
                f"artifact: {CI_RUN_EVIDENCE_OUTPUT_PATH}"
            )
        elif kind == "local-ci-parity":
            lcp_result = local_ci_parity(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            lcp_status = str(lcp_result.get("gate_status") or "")
            step_exit_code = 0 if lcp_status == "PASSED" else 1
            step_stdout = (
                f"local-ci-parity: {lcp_status}\n"
                f"decision_id: {lcp_result.get('decision_id')}\n"
                f"round_id: {lcp_result.get('round_id')}\n"
                f"report_id: {lcp_result.get('report_id')}\n"
                f"required_parity_gaps: {len(lcp_result.get('required_parity_gaps') or [])}\n"
                f"local_transcript_gaps: {len(lcp_result.get('local_transcript_gaps') or [])}\n"
                f"artifact: {LOCAL_CI_PARITY_OUTPUT_PATH}"
            )
        elif kind in {
            "ci-observation-schema",
            "ci-observation-handoff",
            "ci-observation-reconcile",
            "ci-artifact-manifest",
            "ci-audit-handoff-bundle",
        }:
            bridge_handlers: dict[str, tuple[Callable[[], dict[str, Any]], str]] = {
                "ci-observation-schema": (
                    lambda: ci_observation_schema(state_dir=state_dir, write_result=True),
                    CI_OBSERVATION_SCHEMA_OUTPUT_PATH,
                ),
                "ci-observation-handoff": (
                    lambda: ci_observation_handoff(state_dir=state_dir, write_result=True),
                    CI_OBSERVATION_HANDOFF_OUTPUT_PATH,
                ),
                "ci-observation-reconcile": (
                    lambda: ci_observation_reconcile(state_dir=state_dir, write_result=True),
                    CI_OBSERVATION_RECONCILE_OUTPUT_PATH,
                ),
                "ci-artifact-manifest": (
                    lambda: ci_artifact_manifest(state_dir=state_dir, repo_root=repo_root, write_result=True),
                    CI_ARTIFACT_MANIFEST_OUTPUT_PATH,
                ),
                "ci-audit-handoff-bundle": (
                    lambda: ci_audit_handoff_bundle(state_dir=state_dir, write_result=True),
                    CI_AUDIT_HANDOFF_BUNDLE_OUTPUT_PATH,
                ),
            }
            handler, artifact_path = bridge_handlers[kind]
            bridge_result = handler()
            bridge_status = str(bridge_result.get("gate_status") or "")
            step_exit_code = 0 if bridge_status == "PASSED" else 1
            step_stdout = (
                f"{kind}: {bridge_status}\n"
                f"decision_id: {bridge_result.get('decision_id')}\n"
                f"round_id: {bridge_result.get('round_id')}\n"
                f"report_id: {bridge_result.get('report_id')}\n"
                f"artifact: {artifact_path}"
            )
        elif kind == "user-solve-layer":
            usl_result = user_solve_layer(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            usl_status = str(usl_result.get("gate_status") or "")
            step_exit_code = 0 if usl_status == "PASSED" else 1
            step_stdout = (
                f"user-solve-layer: {usl_status}\n"
                f"decision_id: {usl_result.get('decision_id')}\n"
                f"round_id: {usl_result.get('round_id')}\n"
                f"report_id: {usl_result.get('report_id')}\n"
                f"artifact: {USER_SOLVE_LAYER_OUTPUT_PATH}"
            )
        elif kind == "user-solve-trace-fallback":
            ustf_result = user_solve_trace_fallback(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            ustf_status = str(ustf_result.get("gate_status") or "")
            step_exit_code = 0 if ustf_status == "PASSED" else 1
            step_stdout = (
                f"user-solve-trace-fallback: {ustf_status}\n"
                f"decision_id: {ustf_result.get('decision_id')}\n"
                f"round_id: {ustf_result.get('round_id')}\n"
                f"report_id: {ustf_result.get('report_id')}\n"
                f"artifact: {USER_SOLVE_TRACE_FALLBACK_OUTPUT_PATH}"
            )
        elif kind == "user-solve-session-bundle":
            ussb_result = user_solve_session_bundle(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            ussb_status = str(ussb_result.get("gate_status") or "")
            step_exit_code = 0 if ussb_status == "PASSED" else 1
            step_stdout = (
                f"user-solve-session-bundle: {ussb_status}\n"
                f"decision_id: {ussb_result.get('decision_id')}\n"
                f"round_id: {ussb_result.get('round_id')}\n"
                f"report_id: {ussb_result.get('report_id')}\n"
                f"artifact: {USER_SOLVE_SESSION_BUNDLE_OUTPUT_PATH}"
            )
        elif kind == "prework-provenance":
            prework_result = prework_provenance(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            prework_status = str(prework_result.get("gate_status") or "")
            step_exit_code = 0 if prework_status == "PASSED" else 1
            step_stdout = (
                f"prework-provenance: {prework_status}\n"
                f"decision_id: {prework_result.get('decision_id')}\n"
                f"round_id: {prework_result.get('round_id')}\n"
                f"report_id: {prework_result.get('report_id')}\n"
                f"artifact: {PREWORK_PROVENANCE_OUTPUT_PATH}"
            )
        elif kind == "governance-fix":
            governance_result = governance_fix(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            governance_status = str(governance_result.get("gate_status") or "")
            step_exit_code = 0 if governance_status == "PASSED" else 1
            step_stdout = (
                f"governance-fix: {governance_status}\n"
                f"decision_id: {governance_result.get('decision_id')}\n"
                f"round_id: {governance_result.get('round_id')}\n"
                f"report_id: {governance_result.get('report_id')}\n"
                f"artifact: {GOVERNANCE_FIX_OUTPUT_PATH}\n"
                f"status_policy_reconcile: {STATUS_POLICY_RECONCILE_OUTPUT_PATH}\n"
                f"doctor_backlog_split: {DOCTOR_BACKLOG_SPLIT_OUTPUT_PATH}"
            )
        elif kind == "cleanup-apply-safety":
            cleanup_result = cleanup_apply_safety(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            cleanup_status = str(cleanup_result.get("gate_status") or "")
            step_exit_code = 0 if cleanup_status == "PASSED" else 1
            step_stdout = (
                f"cleanup-apply-safety: {cleanup_status}\n"
                f"decision_id: {cleanup_result.get('decision_id')}\n"
                f"round_id: {cleanup_result.get('round_id')}\n"
                f"report_id: {cleanup_result.get('report_id')}\n"
                f"artifact: {CLEANUP_APPLY_SAFETY_OUTPUT_PATH}\n"
                f"snapshot: {CLEANUP_APPLY_SAFETY_SNAPSHOT_OUTPUT_PATH}"
            )
        elif kind == "governance-operations-bundle":
            operations_result = governance_operations_bundle(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            operations_status = str(operations_result.get("gate_status") or "")
            step_exit_code = 0 if operations_status == "PASSED" else 1
            step_stdout = (
                f"governance-operations-bundle: {operations_status}\n"
                f"decision_id: {operations_result.get('decision_id')}\n"
                f"round_id: {operations_result.get('round_id')}\n"
                f"report_id: {operations_result.get('report_id')}\n"
                f"artifact: {GOVERNANCE_OPERATIONS_BUNDLE_OUTPUT_PATH}\n"
                f"snapshot: {GOVERNANCE_OPERATIONS_BUNDLE_SNAPSHOT_OUTPUT_PATH}"
            )
        elif kind == "user-solve-control-plane":
            uscp_result = user_solve_control_plane(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            uscp_status = str(uscp_result.get("gate_status") or "")
            step_exit_code = 0 if uscp_status == "PASSED" else 1
            step_stdout = (
                f"user-solve-control-plane: {uscp_status}\n"
                f"decision_id: {uscp_result.get('decision_id')}\n"
                f"round_id: {uscp_result.get('round_id')}\n"
                f"report_id: {uscp_result.get('report_id')}\n"
                f"artifact: {USER_SOLVE_CONTROL_PLANE_OUTPUT_PATH}"
            )
        elif kind == "user-solve-local-frontend-mvp":
            uslfm_result = user_solve_local_frontend_mvp(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            uslfm_status = str(uslfm_result.get("gate_status") or "")
            step_exit_code = 0 if uslfm_status == "PASSED" else 1
            step_stdout = (
                f"user-solve-local-frontend-mvp: {uslfm_status}\n"
                f"decision_id: {uslfm_result.get('decision_id')}\n"
                f"round_id: {uslfm_result.get('round_id')}\n"
                f"report_id: {uslfm_result.get('report_id')}\n"
                f"artifact: {USER_SOLVE_LOCAL_FRONTEND_MVP_OUTPUT_PATH}\n"
                f"snapshot: {USER_SOLVE_FRONTEND_MVP_SNAPSHOT_OUTPUT_PATH}"
            )
        elif kind == "user-solve-cli":
            proc = runner(command)
            step_exit_code = proc.returncode
            step_stdout = proc.stdout or ""
            step_stderr = proc.stderr or ""
        elif kind == "project-cli":
            proc = runner(command)
            step_exit_code = proc.returncode
            step_stdout = proc.stdout or ""
            step_stderr = proc.stderr or ""
        elif kind == "final-check":
            fc_result = final_check(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
                close_round_in_progress=True,
            )
            fc_status = str(fc_result.get("gate_status") or "")
            step_exit_code = _final_check_exit_code(fc_status)
            step_stdout = f"final-check: {fc_status}"
            fc_blockers = [str(item) for item in (fc_result.get("blocking_reasons") or [])]
            if fc_blockers:
                step_stdout += "\nblocking_reasons:\n" + "\n".join(f"- {item}" for item in fc_blockers)
        else:
            # Unknown gate kind — refuse to execute
            skipped_steps.append({
                "name": step_name,
                "command": command,
                "kind": kind,
                "reason": f"no direct handler for kind {kind!r}",
            })
            blocking_reasons.append(f"step {step_name} refused: no direct handler for kind {kind!r}")
            break

        _append_command_block_to_closeout_log(
            state_dir,
            command=command,
            stdout=step_stdout,
            stderr=step_stderr,
            exit_code=step_exit_code,
            decision_id=decision_id,
            round_id=requested_round_id,
        )
        _record_top_level_if_authorized(
            command=command,
            stdout=step_stdout,
            stderr=step_stderr,
            exit_code=step_exit_code,
        )
        executed_steps.append({
            "name": step_name,
            "command": command,
            "kind": kind,
            "expected_exit_codes": expected,
            "exit_code": step_exit_code,
            "status": "PASSED" if step_exit_code in expected else "FAILED",
        })

        if step_exit_code not in expected:
            blocking_reasons.append(
                f"step {step_name} exited {step_exit_code}, expected {expected}: {command}"
            )
            break

        # Refresh codex_execution_report.md after command-plan-json so
        # report-summary synthesis and final-check see current round IDs.
        if step_name == "command-plan-json":
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            # Regenerate auto-summary after report refresh so it stays
            # consistent with the live codex_report_summary.
            build_report_summary_synthesis(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
            )
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
        if step_name == "execute-decision":
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
        # Refresh codex_execution_report.md after final-check so
        # status/acceptance are derived from the final gate result
        # before close-round runs.
        if step_name == "final-check":
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            # Regenerate auto-summary after report refresh so it stays
            # consistent with the live codex_report_summary.
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
        if step_name in {
            "audit-readiness-packet",
            "current-handoff-packet",
            "local-execution-bundle",
            "codex-prompt-packet",
            "audit-precheck",
            "ci-workflow-coverage",
            "ci-workflow-readiness",
            "ci-run-evidence",
            "local-ci-parity",
            "ci-observation-schema",
            "ci-observation-handoff",
            "ci-observation-reconcile",
            "ci-artifact-manifest",
            "ci-audit-handoff-bundle",
        }:
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
            refreshed_el = execution_log(state_dir=state_dir, write_result=True)
            refreshed_el_status = str(refreshed_el.get("gate_status") or "")
            refreshed_el_exit = 0 if refreshed_el_status == "PASSED" else 1
            refreshed_el_stdout = (
                f"execution-log: {refreshed_el_status}\n"
                f"decision_id: {refreshed_el.get('decision_id')}\n"
                f"round_id: {refreshed_el.get('round_id')}\n"
                f"source: {refreshed_el.get('source')}\n"
                f"artifact: {EXECUTION_LOG_OUTPUT_PATH}\n"
                f"recommended_next_action: {refreshed_el.get('recommended_next_action') or 'no_action_required'}"
            )
            _record_top_level_if_authorized(
                command=f"python -m reverse_agent.project_gate execution-log --state-dir {state_dir}",
                stdout=refreshed_el_stdout,
                stderr="",
                exit_code=refreshed_el_exit,
            )
            # Recording the refreshed execution-log block mutates
            # pytest_result.txt, so regenerate execution_log.json once more
            # after the transcript is stable. Otherwise its provenance hash is
            # immediately stale before the following final-check.
            execution_log(state_dir=state_dir, write_result=True)

    # 7. Run after-close final-check only if close-round succeeded
    if close_round_executed and not blocking_reasons:
        # Refresh report to include round_close_snapshot.json in
        # generated_artifacts and files_changed after close-round
        # creates the close snapshot.
        _refresh_codex_report_for_closeout(
            state_dir=state_dir,
            repo_root=repo_root,
            decision_id=decision_id,
            round_id=requested_round_id,
            include_close_snapshot=True,
        )
        # Regenerate auto-summary after report refresh so it stays
        # consistent with the live codex_report_summary.
        report_auto_summary(state_dir=state_dir, write_result=True)
        _sync_auto_summary_to_report(state_dir)
        # close-round just appended to the closeout execution log. Refresh the
        # derived execution_log before final-check-after-close validates hybrid
        # provenance against the now-current closeout log.
        execution_log(state_dir=state_dir, write_result=True)
        # Re-copy refreshed report/pytest to the round archive BEFORE
        # running final-check-after-close so that the archived copies
        # match the live copies when the check runs.
        _archive_dir = state_dir / "rounds" / requested_round_id
        if _archive_dir.exists():
            import shutil as _shutil
            for _name in (LEGACY_EXECUTION_REPORT_NAME, NEUTRAL_EXECUTION_REPORT_NAME, "pytest_result.txt"):
                _src = state_dir / _name
                if _src.exists():
                    _shutil.copy2(_src, _archive_dir / _name)
            _ensure_neutral_report_archive_manifest_entry(state_dir=state_dir, round_id=round_id)
        audit_after_close_step = next(
            (s for s in steps if s["name"] == "audit-readiness-packet-after-close"),
            None,
        )
        if audit_after_close_step:
            command = audit_after_close_step["command"]
            expected = audit_after_close_step["expected_exit_codes"]
            ar_result = audit_readiness_packet(state_dir=state_dir, write_result=True)
            ar_status = str(ar_result.get("gate_status") or "")
            ar_exit_code = 0 if ar_status == "PASSED" else 1
            ar_stdout = (
                f"audit-readiness-packet: {ar_status}\n"
                f"decision_id: {ar_result.get('decision_id')}\n"
                f"round_id: {ar_result.get('round_id')}\n"
                f"readiness_status: {ar_result.get('readiness_status')}\n"
                f"artifact: {AUDIT_READINESS_PACKET_OUTPUT_PATH}"
            )
            _append_command_block_to_closeout_log(
                state_dir,
                command=command,
                stdout=ar_stdout,
                stderr="",
                exit_code=ar_exit_code,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            _record_top_level_if_authorized(
                command=command,
                stdout=ar_stdout,
                stderr="",
                exit_code=ar_exit_code,
            )
            executed_steps.append({
                "name": "audit-readiness-packet-after-close",
                "command": command,
                "kind": "audit-readiness-packet",
                "expected_exit_codes": expected,
                "exit_code": ar_exit_code,
                "status": "PASSED" if ar_exit_code in expected else "FAILED",
            })
            if ar_exit_code not in expected:
                blocking_reasons.append(
                    f"step audit-readiness-packet-after-close exited {ar_exit_code}, expected {expected}"
                )
            _refresh_codex_report_for_closeout(
                state_dir=state_dir,
                repo_root=repo_root,
                decision_id=decision_id,
                round_id=requested_round_id,
                include_close_snapshot=True,
            )
            current_handoff_packet(state_dir=state_dir, write_result=True)
            local_execution_bundle(state_dir=state_dir, write_result=True)
            codex_prompt_packet(state_dir=state_dir, write_result=True)
            audit_precheck(state_dir=state_dir, write_result=True)
            report_auto_summary(state_dir=state_dir, write_result=True)
            _sync_auto_summary_to_report(state_dir)
            execution_log(state_dir=state_dir, write_result=True)
            if _archive_dir.exists():
                import shutil as _shutil
                for _name in (LEGACY_EXECUTION_REPORT_NAME, NEUTRAL_EXECUTION_REPORT_NAME, "pytest_result.txt"):
                    _src = state_dir / _name
                    if _src.exists():
                        _shutil.copy2(_src, _archive_dir / _name)
                _ensure_neutral_report_archive_manifest_entry(state_dir=state_dir, round_id=round_id)

        after_close_step = next(
            (
                s for s in steps
                if s["name"] in {"final-check-after-audit-readiness", "final-check-after-close"}
            ),
            None,
        )
        if after_close_step:
            after_close_step_name = str(after_close_step.get("name") or "final-check-after-close")
            command = after_close_step["command"]
            kind = after_close_step["kind"]
            expected = after_close_step["expected_exit_codes"]
            fc_result = final_check(
                state_dir=state_dir,
                repo_root=repo_root,
                write_result=True,
                close_round_in_progress=True,
            )
            fc_status = str(fc_result.get("gate_status") or "")
            fc_exit_code = _final_check_exit_code(fc_status)
            fc_stdout = f"final-check: {fc_status}"
            fc_blockers = [str(item) for item in (fc_result.get("blocking_reasons") or [])]
            if fc_blockers:
                fc_stdout += "\nblocking_reasons:\n" + "\n".join(f"- {item}" for item in fc_blockers)
            _append_command_block_to_closeout_log(
                state_dir,
                command=command,
                stdout=fc_stdout,
                stderr="",
                exit_code=fc_exit_code,
                decision_id=decision_id,
                round_id=requested_round_id,
            )
            _record_top_level_if_authorized(
                command=command,
                stdout=fc_stdout,
                stderr="",
                exit_code=fc_exit_code,
            )
            executed_steps.append({
                "name": after_close_step_name,
                "command": command,
                "kind": kind,
                "expected_exit_codes": expected,
                "exit_code": fc_exit_code,
                "status": "PASSED" if fc_exit_code in expected else "FAILED",
            })
            # Recording final-check-after-close mutates the closeout log and
            # may append a top-level transcript block; refresh execution_log so
            # subsequent report/final artifacts do not immediately become stale.
            execution_log(state_dir=state_dir, write_result=True)
            if fc_exit_code not in expected:
                blocking_reasons.append(
                    f"step {after_close_step_name} exited {fc_exit_code}, expected {expected}"
                )
        # Refresh report again after final-check-after-close to pick up the
        # regenerated final_gate_result.json and ensure tests_ran/status are
        # current.  Then re-copy refreshed files to the round archive so that
        # archived_pytest_result_matches_live_pytest_result and
        # archived_report_matches_live_report stay consistent after the
        # after-close refresh and final-check-after-close modified the live copies.
        _refresh_codex_report_for_closeout(
            state_dir=state_dir,
            repo_root=repo_root,
            decision_id=decision_id,
            round_id=requested_round_id,
            include_close_snapshot=True,
        )
        # Regenerate auto-summary after final report refresh so it stays
        # consistent with the live codex_report_summary.
        report_auto_summary(state_dir=state_dir, write_result=True)
        _sync_auto_summary_to_report(state_dir)
        if _archive_dir.exists():
            import shutil as _shutil
            for _name in (LEGACY_EXECUTION_REPORT_NAME, NEUTRAL_EXECUTION_REPORT_NAME, "pytest_result.txt"):
                _src = state_dir / _name
                if _src.exists():
                    _shutil.copy2(_src, _archive_dir / _name)
            _ensure_neutral_report_archive_manifest_entry(state_dir=state_dir, round_id=round_id)
        if close_round_result is not None:
            live_report = _read_execution_report_summary(state_dir)
            live_status = str(live_report.get("status") or "")
            live_acceptance = str(live_report.get("acceptance_recommendation") or "")
            if live_status:
                close_round_result["report_status"] = live_status
            if live_report.get("report_id"):
                close_round_result["report_id"] = live_report.get("report_id")
            status_snapshot = close_round_result.get("status_summary")
            if isinstance(status_snapshot, dict):
                status_snapshot["report_status"] = live_status
                status_snapshot["report_acceptance_recommendation"] = live_acceptance
                status_snapshot["decision_execution_state"] = (
                    "CONSUMED_BY_SUCCESS_REPORT"
                    if live_status == "SUCCESS"
                    else "CONSUMED_BY_NON_SUCCESS_REPORT"
                )

    # 8. Determine status from both top-level and nested closeout evidence.
    if close_round_result is not None:
        _normalize_closed_close_round_result_for_success(close_round_result)
    for reason in _run_closeout_internal_blocking_reasons(
        executed_steps=executed_steps,
        skipped_steps=skipped_steps,
        close_round_result=close_round_result,
    ):
        if reason not in blocking_reasons:
            blocking_reasons.append(reason)

    failed_pytest_blocks = _pytest_result_failed_command_blocks(_read_text(pytest_path))
    # Exclude diagnostic commands (report-summary, final-check, execution-log)
    # from failed blocks check, as they are allowed to exit 1 per command_plan.
    DIAGNOSTIC_KINDS = {"doctor", "report-summary", "final-check", "execution-log"}
    # Also exclude run-closeout for the current round — its exit code is the
    # result being computed, not a pre-existing failure.
    current_round_id = str(requested_round_id or "")
    failed_pytest_blocks = [
        fb for fb in failed_pytest_blocks
        if fb.get("kind") not in DIAGNOSTIC_KINDS
        and not (
            fb.get("kind") == "run-closeout"
            and current_round_id
            and current_round_id in str(fb.get("command", ""))
        )
    ]
    if failed_pytest_blocks:
        failed_commands = [
            f"{item.get('command')} (exit={item.get('exit_code')})"
            for item in failed_pytest_blocks
        ]
        blocking_reasons.append(
            "pytest_result.txt contains failed command block(s): "
            + "; ".join(failed_commands)
        )

    closeout_status = _run_closeout_status(
        blocking_reasons=blocking_reasons,
        warnings=warnings,
    )

    result = {
        "schema_version": GATE_RESULT_SCHEMA_VERSION,
        "gate_name": RUN_CLOSEOUT_NAME,
        "closeout_status": closeout_status,
        "decision_id": decision_id,
        "round_id": requested_round_id,
        "generated_at": _now_iso(),
        "executed_steps": executed_steps,
        "skipped_steps": skipped_steps,
        "startup_blocks": [],
        "close_round_result": close_round_result,
        "blocking_reasons": blocking_reasons,
        "warnings": warnings,
        "recommended_next_action": _run_closeout_recommended_next_action(closeout_status),
        "artifacts": {
            "command_plan": COMMAND_PLAN_OUTPUT_PATH,
            "run_closeout_result": RUN_CLOSEOUT_OUTPUT_PATH,
        },
    }

    if write_result:
        out_dir = state_dir / "gates"
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / RUN_CLOSEOUT_RESULT_NAME).write_text(
            json.dumps(result, ensure_ascii=True, indent=2) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        _append_command_block_to_pytest_result(
            pytest_path,
            command=run_closeout_command,
            stdout=_run_closeout_output_text(result),
            stderr="",
            exit_code=_run_closeout_exit_code(closeout_status),
        )
        archive_dir = state_dir / "rounds" / requested_round_id
        if archive_dir.exists():
            import shutil as _shutil
            for name in (LEGACY_EXECUTION_REPORT_NAME, NEUTRAL_EXECUTION_REPORT_NAME, "pytest_result.txt"):
                source = state_dir / name
                if source.exists():
                    _shutil.copy2(source, archive_dir / name)
            _refresh_manifest_status(state_dir=state_dir, round_id=requested_round_id)
        _refresh_post_run_closeout_evidence(
            state_dir=state_dir,
            repo_root=repo_root,
            decision_id=decision_id,
            round_id=requested_round_id,
        )
    return result


